html:
{% set products = shopProducts(data) %}
{% set layout = data.layout in ['list', 'slider'] ? data.layout : 'grid' %}
<section class="relative {{ section.spacing }}" id="{{ section.slug }}-{{ section.index }}">
    <div class="container">
        {% if data.subtitle or data.title or data.description %}
            <div class="grid grid-cols-1 pb-8 text-center">
                {% if data.subtitle %}
                    <h6 class="text-primary text-base font-medium uppercase mb-2">{{ data.subtitle }}</h6>
                {% endif %}
                {% if data.title %}
                    <h3 class="mb-4 md:text-2xl text-xl font-medium">{{ data.title }}</h3>
                {% endif %}
                {% if data.description %}
                    <div class="rich-content text-muted max-w-xl mx-auto">{{ data.description|raw }}</div>
                {% endif %}
            </div>
        {% endif %}

        {% if products is empty %}
            <p class="text-center text-muted">{{ 'No products found.'|_ }}</p>
        {% elseif layout == 'list' %}
            <div class="grid grid-cols-1 lg:grid-cols-2 gap-6 mt-8">
                {% for product in products %}
                    {% partial 'shop/product-row' product=product %}
                {% endfor %}
            </div>
        {% elseif layout == 'slider' %}
            <div class="products-slider relative mt-8">
                <div class="products-track flex gap-6 overflow-x-auto snap-x snap-mandatory scroll-smooth pb-2">
                    {% for product in products %}
                        <div class="products-slide shrink-0 snap-start">
                            {% partial 'shop/product-card' product=product %}
                        </div>
                    {% endfor %}
                </div>
                <button type="button" class="products-prev absolute top-1/2 -translate-y-1/2 start-0 -ms-3 z-10 flex size-10 items-center justify-center rounded-full bg-surface text-xl shadow duration-300 hover:text-primary dark:bg-night-surface" aria-label="{{ 'Previous'|_ }}" hidden>
                    <i class="ri-arrow-left-s-line rtl:rotate-180"></i>
                </button>
                <button type="button" class="products-next absolute top-1/2 -translate-y-1/2 end-0 -me-3 z-10 flex size-10 items-center justify-center rounded-full bg-surface text-xl shadow duration-300 hover:text-primary dark:bg-night-surface" aria-label="{{ 'Next'|_ }}" hidden>
                    <i class="ri-arrow-right-s-line rtl:rotate-180"></i>
                </button>
            </div>
        {% else %}
            <div class="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6 mt-8">
                {% for product in products %}
                    {% partial 'shop/product-card' product=product %}
                {% endfor %}
            </div>
        {% endif %}
    </div>
</section>

css:
& .products-track {
    scrollbar-width: none;
}

& .products-track::-webkit-scrollbar {
    display: none;
}

& .products-slide {
    width: calc((100% - 1.5rem) / 2);
}

@media (min-width: 768px) {
    & .products-slide {
        width: calc((100% - 3rem) / 3);
    }
}

@media (min-width: 1024px) {
    & .products-slide {
        width: calc((100% - 4.5rem) / 4);
    }
}

js:
var track = root.querySelector('.products-track');
if (!track) {
    return;
}

var prev = root.querySelector('.products-prev');
var next = root.querySelector('.products-next');
var rtl = window.getComputedStyle(track).direction === 'rtl';

var update = function () {
    var max = track.scrollWidth - track.clientWidth;
    var position = Math.abs(track.scrollLeft);
    prev.hidden = position <= 1;
    next.hidden = position >= max - 1;
};

var move = function (direction) {
    track.scrollBy({ left: direction * track.clientWidth * (rtl ? -1 : 1), behavior: 'smooth' });
};

prev.addEventListener('click', function () {
    move(-1);
});
next.addEventListener('click', function () {
    move(1);
});
track.addEventListener('scroll', update, { passive: true });
window.addEventListener('resize', update);
update();
